 const t=game.target;if(t){const r=t.type==='planet'?t.r+19:t.type==='belt'?85:t.r+16;ctx.strokeStyle='#e5b67a';ctx.lineWidth=1.5/cam.zoom;for(let i=0;i<4;i++){const a=i*Math.PI/2+clock*.03;ctx.beginPath();ctx.arc(t.x,t.y,r,a+.15,a+.5);ctx.stroke();}}
 ctx.restore();
 if(started&&!panel&&!game.s.docked&&t){const sx=(t.x-cam.x)*cam.zoom+width/2,sy=(t.y-cam.y)*cam.zoom+height/2,margin=width<650?65:105;if(sx<margin||sx>width-margin||sy<165||sy>height-170){const dx=sx-width/2,dy=sy-height/2,a=Math.atan2(dy,dx),rx=width/2-margin,ry=height/2-165;if(ry>20){const k=Math.min(rx/Math.max(.01,Math.abs(dx)),ry/Math.max(.01,Math.abs(dy))),x=width/2+dx*k,y=height/2+dy*k;ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#e6b67c';ctx.beginPath();ctx.moveTo(8,0);ctx.lineTo(-5,-5);ctx.lineTo(-5,5);ctx.closePath();ctx.fill();ctx.restore();}}}
 if(game.jump){const progress=game.jump.progress/3;ctx.globalAlpha=progress*.8;ctx.strokeStyle='#91eadd';ctx.lineWidth=1;for(let i=0;i<75;i++){const a=i*2.39996,r=30+(i*71+clock*800)%Math.max(width,height);ctx.beginPath();ctx.moveTo(width/2+Math.cos(a)*r,height/2+Math.sin(a)*r);ctx.lineTo(width/2+Math.cos(a)*r*(1.1+progress*.7),height/2+Math.sin(a)*r*(1.1+progress*.7));ctx.stroke();}ctx.globalAlpha=1;}
