function drawRadar(){const c=$('radar');if(!c)return;const r=c.getContext('2d');r.clearRect(0,0,268,268);r.fillStyle='#0b1c2577';r.strokeStyle='#44697388';r.lineWidth=1.5;r.beginPath();r.arc(134,134,123,0,6.28);r.fill();r.stroke();r.beginPath();r.arc(134,134,64,0,6.28);r.strokeStyle='#38525e99';r.stroke();r.beginPath();r.moveTo(12,134);r.lineTo(256,134);r.moveTo(134,12);r.lineTo(134,256);r.stroke();r.save();r.beginPath();r.arc(134,134,121,0,6.28);r.clip();const p=game.player;for(const o of [...(game.sys.hasStation?[game.station]:[]),game.star,...game.patrols,...game.planets,...game.asteroids,...game.enemies]){const x=134+(o.x-p.x)*.054,y=134+(o.y-p.y)*.054;r.fillStyle=o.type==='enemy'?'#ee8d87':o.type==='planet'?'#85b8cf':o.type==='asteroid'?'#797b76':'#91efd9';r.fillRect(x-2,y-2,o.type==='station'?7:4,o.type==='station'?7:4);}r.restore();r.save();r.translate(134,134);r.rotate(p.angle);r.fillStyle='#a7f0df';r.beginPath();r.moveTo(9,0);r.lineTo(-5,5);r.lineTo(-5,-5);r.closePath();r.fill();r.restore();}
let last=performance.now(),lastFireSound=0;
function loop(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(!document.hidden){clock+=dt;if(started&&!panel){const wasDocked=game.s.docked;const input={aim:touch.aim,thrust:Math.max(touch.thrust,keys.w||keys.arrowup?1:0),turn:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),fire:touch.fire||keys[' '],boost:touch.boost||keys.shift,brake:keys.s||keys.arrowdown};game.update(dt,input);if(input.fire&&!game.surface&&!game.s.docked&&now-lastFireSound>240){sound('fire');lastFireSound=now;}if(!wasDocked&&game.s.docked)openPanel('station');}render();if(now-lastHUD>120){updateHUD();drainEvents();const p=game.surface||game.player;engine.update({moving:Math.min(1,Math.hypot(p.vx,p.vy)/(game.surface?140:getStats(game.s).speed)),boost:game.boost||touch.boost,volume:game.s.engineVolume,enabled:game.s.sound,paused:!started||!!panel||game.s.docked,surface:!!game.surface});lastHUD=now;}if(started&&now-lastStore>4000){save();lastStore=now;}}requestAnimationFrame(loop);}
if(!ctx){document.body.innerHTML='<div class="canvas-fallback">Farbound needs an Android browser with Canvas support. Please open it in an updated Chrome browser.</div>';}else{buildHUD();showWelcome();resize();requestAnimationFrame(loop);}
